def transform(g):
 h,w=len(g),len(g[0]); from collections import Counter
 cnt=Counter(x for r in g for x in r); col=next((c for c,n in cnt.items() if c not in (0,5,9) and n>1), None)
 if col is None: col=next((c for c,n in cnt.items() if c not in (0,5,9)),None)
 pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==col]
 # object as shape; find exact zero matches in 8 orientations
 shapes=[]
 for flip in [1,-1]:
  for rot in range(4):
   q=[]
   for y,x in pts:
    x*=flip
    for _ in range(rot): y,x=x,-y
    q.append((y,x))
   my=min(y for y,x in q); mx=min(x for y,x in q)
   shapes.append(set((y-my,x-mx) for y,x in q))
 out=[r[:] for r in g]
 for shape in shapes:
  mh=max(y for y,x in shape)+1; mw=max(x for y,x in shape)+1
  for y in range(h-mh+1):
   for x in range(w-mw+1):
    if all(g[y+a][x+b]==0 for a,b in shape):
     for a,b in shape: out[y+a][x+b]=col
 return out
